// A small pure function to compute the sum of a slice a[start..end].
// We place it in the spec world so that it can be used in pre/post and invariants.
#[verifier::spec]
fn slice_sum(a: &Vec<i32>, start: usize, end: usize) -> i32 {
    if start >= end {
        0
    } else {
        a[start] + slice_sum(a, start + 1, end)
    }
}

